        SupportArticle::firstOrCreate(['slug' => Str::slug('Tracking your enquiries')], ['support_category_id' => $category->id, 'title' => 'Tracking your enquiries', 'summary' => 'Open your customer workspace and Collaborations & notifications to review your requests and replies.', 'content' => 'Open your customer workspace and Collaborations & notifications to review your requests and replies. Follow the status of each enquiry there. If you need help, include a relevant reference in a support ticket; do not post private project details publicly.', 'status' => 'published', 'sort_order' => 1, 'published_at' => now()]);
