        SupportArticle::firstOrCreate(['slug' => Str::slug('Invoices and billing questions')], ['support_category_id' => $category->id, 'title' => 'Invoices and billing questions', 'summary' => 'Request collaboration invoices directly from the party receiving payment.', 'content' => 'Request collaboration invoices directly from the party receiving payment. Colliva does not currently generate invoices for payments made directly between collaborators. For a platform fee or billing question, contact support and include the relevant reference without card numbers or banking secrets.', 'status' => 'published', 'sort_order' => 1, 'published_at' => now()]);
